import '../../../../globals.js';
import { alpenglow } from '../../alpenglow.js';
let globalId = 1;
export class Resource {
    constructor(resource) {
        this.resource = resource;
        this.id = globalId++;
    }
}
alpenglow.register('Resource', Resource);
